  "claim": {
    "component_id": "C029.component",
    "value": "Elevated weekly late-start rates in consecutive weeks are a temporal pattern to seek.",
    "scope": "A prospective observation category; the baseline or threshold defining an elevated rate is unspecified.",
    "provenance": {
      "refs": [
        {
          "source_id": "P015",
          "role": "SUPPORT"
        },
        {
          "source_id": "P018",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans identify consecutive elevated weekly rates as a pattern to seek and explicitly characterize the signals as prospective observations."
    }
  },
  "signal_basis": {
    "component_id": "C029.signal_basis",
    "value": "Record turnaround events comparably, review daily, and summarize weekly late bookings divided by all bookings, displaying booking denominators and missing-record counts. Seek elevated rates across consecutive weeks.",
    "scope": "A prospective temporal observation using consistent start definitions; collection is not equated with actual start unless their relationship is verified. No numerical elevation threshold is specified.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
