          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply comparable recording, start-definition safeguards, weekly rate construction, reporting context, and the prospective pattern."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C029.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is needed to license this bounded observation-category claim."
    }
  },
  "rationale": "Consecutive weekly rate observations constitute a temporal sequence, and repeated elevation is a temporal pattern within it. The claim only identifies a pattern to seek; it asserts neither an observed finding nor a causal or statistical conclusion.",
  "uncertainty": "The unspecified elevation baseline limits how the category can be operationalized, but does not undermine this explicitly bounded claim.",
  "anomalies": []
